function concat(parts: Uint8Array[]) { const bytes = new Uint8Array(parts.reduce((sum, part) => sum + part.length, 0)); let at = 0; for (const part of parts) { bytes.set(part, at); at += part.length; } return bytes; }
async function fixtureZip(parts: Array<{ name: string; content: string }>, compressed = false) {
  const entries: Uint8Array[] = []; const central: Uint8Array[] = []; let offset = 0;
  for (const part of parts) {
    const name = enc.encode(part.name); const source = enc.encode(part.content);
    const payload = compressed ? new Uint8Array(await new Response(new Blob([source]).stream().pipeThrough(new CompressionStream("deflate-raw"))).arrayBuffer()) : source;
    const local = concat([integer(0x04034b50, 4), integer(20, 2), integer(0x800, 2), integer(compressed ? 8 : 0, 2), integer(0, 4), integer(crc(source), 4), integer(payload.length, 4), integer(source.length, 4), integer(name.length, 2), integer(0, 2), name, payload]);
    entries.push(local);
    central.push(concat([integer(0x02014b50, 4), integer(20, 2), integer(20, 2), integer(0x800, 2), integer(compressed ? 8 : 0, 2), integer(0, 4), integer(crc(source), 4), integer(payload.length, 4), integer(source.length, 4), integer(name.length, 2), integer(0, 2), integer(0, 2), integer(0, 2), integer(0, 2), integer(0, 4), integer(offset, 4), name]));
    offset += local.length;
  }
  const directory = concat(central);
  return file(new Blob([concat([...entries, directory, integer(0x06054b50, 4), integer(0, 2), integer(0, 2), integer(parts.length, 2), integer(parts.length, 2), integer(directory.length, 4), integer(offset, 4), integer(0, 2)])]));
}
async function customWorkbook(sheets: string[], { date1904 = false, shared = "", styles = "", compressed = false, paths = sheets.map((_, index) => `worksheets/custom-${index + 29}.xml`) } = {}) {
  const workbook = `<s:workbook xmlns:s="${ns}" xmlns:link="${relationshipNs}"><s:workbookPr date1904="${date1904 ? 1 : 0}"/><s:sheets>${sheets.map((_, index) => `<s:sheet name="Лист ${index + 1}" sheetId="${index + 1}" link:id="custom${index}"/>`).join("")}</s:sheets></s:workbook>`;
  const rels = `<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${paths.map((path, index) => `<Relationship Id="custom${index}" Type="${relationshipNs}/worksheet" Target="${path}"/>`).join("")}<Relationship Id="strings" Type="${relationshipNs}/sharedStrings" Target="strings.xml"/>${styles ? `<Relationship Id="styles" Type="${relationshipNs}/styles" Target="styles.xml"/>` : ""}</Relationships>`;
  return fixtureZip([{ name: "xl/workbook.xml", content: workbook }, { name: "xl/_rels/workbook.xml.rels", content: rels }, ...sheets.map((source, index) => ({ name: paths[index].startsWith("/") ? paths[index].slice(1) : `xl/${paths[index]}`, content: source })), ...(shared ? [{ name: "xl/strings.xml", content: `<sst xmlns="${ns}">${shared}</sst>` }] : []), ...(styles ? [{ name: "xl/styles.xml", content: styles }] : [])], compressed);
}
async function unpackStored(blob: Blob) {
  const data = await blob.arrayBuffer(); const view = new DataView(data); const parts: Array<{ name: string; content: string }> = []; let at = 0;
  while (view.getUint32(at, true) === 0x04034b50) { const length = view.getUint32(at + 18, true); const nameLength = view.getUint16(at + 26, true); const extraLength = view.getUint16(at + 28, true); const name = dec.decode(new Uint8Array(data, at + 30, nameLength)); const start = at + 30 + nameLength + extraLength; parts.push({ name, content: dec.decode(new Uint8Array(data, start, length)) }); at = start + length; }
  return parts;
}
